    mn=[[n+1]*(n+2) for _ in range(n+1)]
    p=2
    for _ in range(m):
        l,r,x=data[p],data[p+1],data[p+2];p+=3
        if r<mn[x][l]: mn[x][l]=r
    for x in range(1,n+1):
        row=mn[x]
        for l in range(n-1,0,-1):
            if row[l+1]<row[l]: row[l]=row[l+1]
    C=[[0]*(n+1) for _ in range(n+1)]
    for i in range(n+1):
        C[i][0]=C[i][i]=1
        for j in range(1,i): C[i][j]=(C[i-1][j-1]+C[i-1][j])%MOD
    dp=[[0]*(n+2) for _ in range(n+2)]
    for i in range(1,n+2): dp[i][i-1]=1
    for l in range(n,0,-1):
        for r in range(l,n+1):
            s=0
            for k in range(l,r+1):
                if mn[k][l]>r:
                    s += C[r-l][k-l]*dp[l][k-1]*dp[k+1][r]
            dp[l][r]=s%MOD
    print(dp[1][n])
