import sys
MOD=998244353

def solve():
    data=list(map(int,sys.stdin.buffer.read().split()))
    n=data[0]
    a=data[1:]
    factors={}
    for i,x in enumerate(a):
        y=x
        d=2
        while d*d<=y:
            if y%d==0:
                c=0
                while y%d==0:
                    y//=d
                    c+=1
                factors.setdefault(d,[0]*(n-1))[i]=c
            d+=1
        if y>1:
            factors.setdefault(y,[0]*(n-1))[i]=1

    ans=1
    for p, exps in factors.items():
        dp=[1]
        processed=1
        for aa in reversed(exps):
            nd=[0]*(len(dp)+aa if aa else len(dp))
            choices=(aa,-aa) if aa else (0,)
            for h,w in enumerate(dp):
                if w==0:
                    continue
                for delta in choices:
                    r=h+delta
                    if r>=0:
                        nd[r]=(nd[r]+w*pow(p,r,MOD))%MOD
                    else:
                        nd[0]=(nd[0]+w*pow(p,(-r)*processed,MOD))%MOD
            dp=nd
            processed+=1
        ans=ans*sum(dp)%MOD
    print(ans)

