from typing import List

class Solution:
    def maxSubarrays(self, n: int, conflictingPairs: List[List[int]]) -> int:
        by_right = [[] for _ in range(n + 1)]
        for i, (a, b) in enumerate(conflictingPairs):
            if a > b:
                a, b = b, a
            by_right[b].append((a, i))

        # The two largest left endpoints among pairs whose right endpoint
        # has been reached, together with the pair identifying each one.
        top1 = (0, -1)
        top2 = (0, -1)
        gains = [0] * len(conflictingPairs)
        base = 0

        for right in range(1, n + 1):
            for left, index in by_right[right]:
                if left > top1[0]:
                    top2, top1 = top1, (left, index)
                elif left > top2[0]:
                    top2 = (left, index)

            base += right - top1[0]
            if top1[1] != -1:
                gains[top1[1]] += top1[0] - top2[0]

        return base + max(gains)

