import sys

def solve():
    data = list(map(int, sys.stdin.buffer.read().split()))
    it = iter(data)
    n, m, q = next(it), next(it), next(it)
    edges = [(next(it)-1, next(it)-1, next(it)) for _ in range(m)]
    queries = []
    for _ in range(q):
        t = next(it)
        if t == 1:
            queries.append((1, next(it)-1))
        else:
            queries.append((2, next(it)-1, next(it)-1))

    INF = 10**30
    closed = [False] * m
    answers = []
    block_size = 25
    p = 0

    while p < q:
        z = p
        block_edges = []
        while z < q and len(block_edges) < block_size:
            if queries[z][0] == 1:
                block_edges.append(queries[z][1])
            z += 1
        future = set(block_edges)

        dist = [[INF] * n for _ in range(n)]
        for i in range(n):
            dist[i][i] = 0
        for k, (a, b, w) in enumerate(edges):
            if not closed[k] and k not in future:
                if w < dist[a][b]:
                    dist[a][b] = dist[b][a] = w

        for k in range(n):
            rowk = dist[k]
            for i in range(n):
                dik = dist[i][k]
                if dik < INF:
                    row = dist[i]
                    for j in range(n):
                        v = dik + rowk[j]
                        if v < row[j]:
                            row[j] = v

        special = sorted({v for e in block_edges for v in edges[e][:2]})
        s = len(special)
        where = {v: i for i, v in enumerate(special)}
        alive = set(block_edges)

        def build_special_distances():
            cur = [[dist[special[i]][special[j]] for j in range(s)]
                   for i in range(s)]
            for e in alive:
                a, b, w = edges[e]
                a, b = where[a], where[b]
                if w < cur[a][b]:
                    cur[a][b] = cur[b][a] = w
            for k in range(s):
                rk = cur[k]
                for i in range(s):
                    ri = cur[i]
                    v = ri[k]
                    for j in range(s):
                        nv = v + rk[j]
                        if nv < ri[j]:
                            ri[j] = nv
            return cur

        special_dist = build_special_distances() if s else []
        for idx in range(p, z):
            query = queries[idx]
            if query[0] == 1:
                e = query[1]
                alive.discard(e)
                closed[e] = True
                special_dist = build_special_distances()
            else:
                _, x, y = query
                ans = dist[x][y]
                if s:
                    left = [dist[x][v] for v in special]
                    right = [dist[v][y] for v in special]
                    for i in range(s):
                        for j in range(s):
                            ans = min(ans, left[i] + special_dist[i][j] + right[j])
                answers.append(str(ans if ans < INF else -1))
        p = z

    sys.stdout.write('\n'.join(answers))

