class Solution:
    def countKReducibleNumbers(self, s: str, k: int) -> int:
        MOD = 1000000007
        length = len(s)
        comb = [[0] * (length + 1) for _ in range(length + 1)]
        comb[0][0] = 1
        for i in range(1, length + 1):
            comb[i][0] = comb[i][i] = 1
            for j in range(1, i):
                comb[i][j] = (comb[i - 1][j - 1] + comb[i - 1][j]) % MOD

        good = [False] * (length + 1)
        for c in range(1, length + 1):
            v = c
            steps = 0
            while v != 1:
                v = v.bit_count()
                steps += 1
            good[c] = steps <= k - 1

        answer = 0
        ones_before = 0
        for i, bit in enumerate(s):
            if bit == '1':
                remaining = length - i - 1
                lo = max(1, ones_before)
                hi = min(length, ones_before + remaining)
                for c in range(lo, hi + 1):
                    if good[c]:
                        answer = (answer + comb[remaining][c - ones_before]) % MOD
                ones_before += 1
        return answer

