import sys
from collections import deque

def main():
    input = sys.stdin.readline
    n = int(input())
    g = [input().strip() for _ in range(n)]

    out = [[[] for _ in range(26)] for _ in range(n)]
    inc = [[[] for _ in range(26)] for _ in range(n)]
    for i, row in enumerate(g):
        for j, ch in enumerate(row):
            if ch != '-':
                k = ord(ch) - 97
                out[i][k].append(j)
                inc[j][k].append(i)

    d = [[-1] * n for _ in range(n)]
    q = deque()
    left = n * n

    for i in range(n):
        d[i][i] = 0
        left -= 1
        q.append((i, i))
    for i, row in enumerate(g):
        for j, ch in enumerate(row):
            if ch != '-' and d[i][j] < 0:
                d[i][j] = 1
                left -= 1
                q.append((i, j))

    while q and left:
        a, b = q.popleft()
        nd = d[a][b] + 2
        for k in range(26):
            if not inc[a][k] or not out[b][k]:
                continue
            for x in inc[a][k]:
                dx = d[x]
                for y in out[b][k]:
                    if dx[y] < 0:
                        dx[y] = nd
                        left -= 1
                        q.append((x, y))

    for row in d:
        print(*row)

