import sys, math

N = int(sys.stdin.readline())

# Put d = x - y.  Then
# N = d * (3*y*y + 3*d*y + d*d).
# Since y >= 1, d^3 < N, so only cube-root many d values are needed.
lo, hi = 0, 1
while hi**3 <= N:
    hi *= 2
while lo + 1 < hi:
    mid = (lo + hi) // 2
    if mid**3 <= N:
        lo = mid
    else:
        hi = mid

for d in range(1, lo + 1):
    if N % d != 0:
        continue
    q = N // d
    # The discriminant of 3*y^2 + 3*d*y + d^2 - q = 0.
    disc = 12 * q - 3 * d * d
    if disc < 0:
        continue
    root = math.isqrt(disc)
    if root * root != disc:
        continue
    numerator = root - 3 * d
    if numerator > 0 and numerator % 6 == 0:
        y = numerator // 6
        if y > 0:
            print(y + d, y)
            break
else:
    print(-1)

