class Solution:
 def lenOfVDiagonal(self, grid: List[List[int]]) -> int:
  n=len(grid); m=len(grid[0]); N=n*m
  dirs=((1,1),(1,-1),(-1,-1),(-1,1))
  ss=[]
  for dr,dc in dirs:
   a0=array('H',[0])*N; a2=array('H',[0])*N
   rs=range(n-1,-1,-1) if dr==1 else range(n)
   cs=range(m-1,-1,-1) if dc==1 else range(m)
   for r in rs:
    for c in cs:
     v=grid[r][c]; k=r*m+c
     nr=r+dr; nc=c+dc
     if v==0 or v==2:
      z=0
      if 0<=nr<n and 0<=nc<m:
       z=(a2 if v==0 else a0)[nr*m+nc]
      if v==0: a0[k]=z+1
      else: a2[k]=z+1
   ss.append((a0,a2))
  ans=1
  for d,(dr,dc) in enumerate(dirs):
   t0=array('H',[0])*N; t2=array('H',[0])*N
   a0,a2=ss[(d+1)%4]
   rs=range(n-1,-1,-1) if dr==1 else range(n)
   cs=range(m-1,-1,-1) if dc==1 else range(m)
   for r in rs:
    for c in cs:
     v=grid[r][c]; k=r*m+c
     if v!=0 and v!=2: continue
     nr=r+dr; nc=c+dc
     x=y=0
     if 0<=nr<n and 0<=nc<m:
      q=nr*m+nc
      if v==0: x=t2[q]; y=a2[q]
      else: x=t0[q]; y=a0[q]
     if v==0: t0[k]=1+max(x,y)
