   for r in range(n):
    for c in range(m):
     if grid[r][c]==1:
      nr=r+dr; nc=c+dc
      val=1
      if 0<=nr<n and 0<=nc<m: val+=t2[nr*m+nc]
      if val>ans: ans=val
  return ans

