from typing import List

class Solution:
    def permute(self, n: int, k: int) -> List[int]:
        fact = [1] * (n + 1)
        for i in range(1, n + 1):
            fact[i] = fact[i - 1] * i

        def completions(odds, evens, required):
            if required == 1:
                if odds != evens and odds != evens + 1:
                    return 0
            else:
                if evens != odds and evens != odds + 1:
                    return 0
            return fact[odds] * fact[evens]

        odds, evens = (n + 1) // 2, n // 2
        used = [False] * (n + 1)
        answer = []
        required = None
        for position in range(n):
            chosen = 0
            for value in range(1, n + 1):
                if used[value] or (required is not None and value % 2 != required):
                    continue
                remaining_odds, remaining_evens = odds, evens
                if value % 2:
                    remaining_odds -= 1
                else:
                    remaining_evens -= 1
                next_required = 0 if value % 2 else 1
                count = (completions(remaining_odds, remaining_evens, next_required)
                         if position + 1 < n else 1)
                if k > count:
                    k -= count
                else:
                    chosen = value
                    break
            if not chosen:
                return []
            used[chosen] = True
            answer.append(chosen)
            if chosen % 2:
                odds -= 1
                required = 0
            else:
                evens -= 1
                required = 1
        return answer

