from typing import List
class Solution:
    def permute(self, n: int, k: int) -> List[int]:
        fact = [1] * (n + 1)
        for i in range(1, n + 1):
            fact[i] = fact[i-1] * i
        def completions(o, e, req):
            if req == 1:
                if not (o == e or o == e + 1):
                    return 0
            else:
                if not (e == o or e == o + 1):
                    return 0
            return fact[o] * fact[e]
        odds = (n + 1) // 2
        evens = n // 2
        used = [False] * (n + 1)
        ans = []
        req = 0
        for pos in range(n):
            chosen = 0
            for x in range(1, n + 1):
                if used[x] or (req and x % 2 != req):
                    continue
                no, ne = odds, evens
                if x % 2: no -= 1
                else: ne -= 1
                nr = 2 if x % 2 else 1
                cnt = completions(no, ne, nr) if pos + 1 < n else 1
                if cnt == 0:
                    continue
                if k > cnt:
                    k -= cnt
                else:
                    chosen = x
                    break
            if not chosen:
                return []
            used[chosen] = True
            ans.append(chosen)
            if chosen % 2: odds -= 1; req = 2
