class Solution:
    def largestPalindrome(self, n: int, k: int) -> str:
        m = (n + 1) // 2
        coeff = []
        for t in range(m):
            if t == n - 1 - t:
                c = pow(10, t, k)
            else:
                c = (pow(10, t, k) + pow(10, n - 1 - t, k)) % k
            coeff.append(c)

        # suff[t] is the set of residues obtainable from positions t onward.
        suff = [0] * (m + 1)
        suff[m] = 1  # residue zero
        for t in range(m - 1, -1, -1):
            c = coeff[t]
            mask = 0
            for d in range(10):
                shift = (d * c) % k
                old = suff[t + 1]
                for r in range(k):
                    if (old >> r) & 1:
                        mask |= 1 << ((shift + r) % k)
            suff[t] = mask

        left = []
        rem = 0
        for t, c in enumerate(coeff):
            first = (t == 0)
            for d in range(9, (0 if first else -1), -1):
                need = (-rem - d * c) % k
                if (suff[t + 1] >> need) & 1:
                    left.append(str(d))
                    rem = (rem + d * c) % k
                    break

        half = ''.join(left)
        if n % 2:
            return half + half[-2::-1]
        return half + half[::-1]

