from typing import List

class Solution:
    def countNonDecreasingSubarrays(self, nums: List[int], k: int) -> int:
        n = len(nums)
        pref = [0] * (n + 1)
        for i, x in enumerate(nums):
            pref[i + 1] = pref[i] + x

        # ng[i] is the first position to the right whose value is greater.
        ng = [-1] * n
        stack = []
        for i in range(n - 1, -1, -1):
            while stack and nums[stack[-1]] <= nums[i]:
                stack.pop()
            ng[i] = stack[-1] if stack else -1
            stack.append(i)

        log = n.bit_length()
        up = [ng[:]]
        edge = [[0] * n]
        for i, q in enumerate(ng):
            if q != -1:
                edge[0][i] = nums[i] * (q - i - 1) - (pref[q] - pref[i + 1])

        for j in range(1, log):
            prev_up, prev_edge = up[-1], edge[-1]
            cur_up = [-1] * n
            cur_edge = [0] * n
            for i, mid in enumerate(prev_up):
                if mid != -1:
                    cur_up[i] = prev_up[mid]
                    cur_edge[i] = prev_edge[i] + prev_edge[mid]
            up.append(cur_up)
            edge.append(cur_edge)

        def cost(left: int, right: int) -> int:
            pos = left
            result = 0
            for j in range(log - 1, -1, -1):
                nxt = up[j][pos]
                if nxt != -1 and nxt <= right:
                    result += edge[j][pos]
                    pos = nxt
            result += nums[pos] * (right - pos) - (pref[right + 1] - pref[pos + 1])
            return result

        answer = 0
        for right in range(n):
            lo, hi = 0, right
            while lo < hi:
                mid = (lo + hi) // 2
                if cost(mid, right) <= k:
                    hi = mid
                else:
                    lo = mid + 1
            answer += right - lo + 1
        return answer

