import sys, heapq

def solve():
    data = list(map(int, sys.stdin.buffer.read().split()))
    if not data:
        return
    n = data[0]
    adj = [[] for _ in range(n)]
    q = 1
    for _ in range(n - 1):
        u, v, w = data[q] - 1, data[q + 1] - 1, data[q + 2]
        q += 3
        adj[u].append((v, w))
        adj[v].append((u, w))

    parent = [-1] * n
    edge_to_parent = [0] * n
    order = [0]
    for v in order:
        for u, w in adj[v]:
            if u != parent[v]:
                parent[u] = v
                edge_to_parent[u] = w
                order.append(u)

    height = [0] * n
    best_child = [-1] * n
    for v in reversed(order):
        for u, w in adj[v]:
            if parent[u] == v and w + height[u] > height[v]:
                height[v] = w + height[u]
                best_child[v] = u

    heap = []
    for u, w in adj[0]:
        if parent[u] == 0:
            heapq.heappush(heap, (-(w + height[u]), u))

    gains = []
    while heap:
        _, v = heapq.heappop(heap)
        gain = 0
        while True:
            gain += edge_to_parent[v]
            chosen = best_child[v]
            for u, w in adj[v]:
                if parent[u] == v and u != chosen:
                    heapq.heappush(heap, (-(w + height[u]), u))
            if chosen == -1:
                break
            v = chosen
        gains.append(gain)

    current = 0
    answer = []
    for k in range(n):
        if k < len(gains):
            current += gains[k]
        answer.append(str(2 * current))
    sys.stdout.write("\n".join(answer))

