    def shortestMatchingSubstring(self, s: str, p: str) -> int:
        a, b, c = p.split('*')
        n = len(s)

        def occurrences(t):
            if not t:
                return [True] * (n + 1)
            m = len(t)
            pi = [0] * m
            for i in range(1, m):
                j = pi[i - 1]
