        while st:
            x,k=st[-1]
            if k<len(ch[x]):
                y=ch[x][k]; st[-1]=(x,k+1); st.append((y,0))
            else: order.append(x); st.pop()
        po=[0]*n
        for j,x in enumerate(order): po[x]=j
        lo=po[:]
        for x in reversed(order):
            for y in ch[x]: lo[x]=min(lo[x],lo[y])
        t='#'+'#'.join(s[x] for x in order)+'#'
        p=[0]*len(t); c=r=0
        for i in range(len(t)):
            if i<r: p[i]=min(r-i,p[2*c-i])
            while i>p[i] and i+1+p[i]<len(t) and t[i-1-p[i]]==t[i+1+p[i]]: p[i]+=1
            if i+p[i]>r: c,r=i,i+p[i]
        return [p[lo[i]+po[i]+1] >= po[i]+1-lo[i] for i in range(n)]

