def solve():
    data=list(map(int,sys.stdin.buffer.read().split()))
    if not data:return
    n,m,s,t=data[:4]; p=4; V=2*n
    head=[-1]*V; to=array('i'); cap=array('b'); cost=array('i'); nxt=array('i')
    def add(a,b,c,w):
        i=len(to); to.extend((b,a)); cap.extend((c,0)); cost.extend((w,-w)); nxt.extend((head[a],head[b])); head[a]=i; head[b]=i+1
    for v in range(n): add(2*v,2*v+1,2 if v==s-1 or v==t-1 else 1,0)
    for _ in range(m):
        u,v=data[p]-1,data[p+1]-1; p+=2
        add(2*u+1,2*v,1,1); add(2*v+1,2*u,1,1)
    src=2*(s-1); snk=2*(t-1)+1; pot=[0]*V; ans=0
    for _ in range(2):
        inf=10**9; dist=[inf]*V; prev=[-1]*V; dist[src]=0; hp=[(0,src)]
        while hp:
            d,x=heapq.heappop(hp)
            if d!=dist[x]: continue
            if x==snk: break
            i=head[x]
            while i!=-1:
                if cap[i]:
                    y=to[i]; nd=d+cost[i]+pot[x]-pot[y]
                    if nd<dist[y]:
