class Solution:
    def maxSubarraySum(self, nums: List[int], k: int) -> int:
        mins = [None] * k
        mins[0] = 0
        prefix = 0
        answer = None
        for index, value in enumerate(nums, 1):
            prefix += value
            remainder = index % k
            if mins[remainder] is not None:
                candidate = prefix - mins[remainder]
                if answer is None or candidate > answer:
                    answer = candidate
            if mins[remainder] is None or prefix < mins[remainder]:
                mins[remainder] = prefix
        return answer

