import heapq

class Solution:
    def minOperations(self, n: int, m: int) -> int:
        length = len(str(n))
        limit = 10 ** length

        prime = [True] * limit
        prime[0] = prime[1] = False
        for p in range(2, int(limit ** 0.5) + 1):
            if prime[p]:
                prime[p * p:limit:p] = [False] * (((limit - 1 - p * p) // p) + 1)

        if prime[n] or prime[m]:
            return -1

        inf = 10 ** 30
        distance = [inf] * limit
        distance[n] = n
        queue = [(n, n)]
        powers = [10 ** i for i in range(length)]

        while queue:
            cost, value = heapq.heappop(queue)
            if cost != distance[value]:
                continue
            if value == m:
                return cost

            for power in powers:
                digit = (value // power) % 10
                if digit < 9:
                    nxt = value + power
                    if not (power == powers[-1] and nxt < power) and not prime[nxt]:
                        new_cost = cost + nxt
                        if new_cost < distance[nxt]:
                            distance[nxt] = new_cost
                            heapq.heappush(queue, (new_cost, nxt))
                if digit > 0:
                    nxt = value - power
                    if not (power == powers[-1] and nxt < power) and not prime[nxt]:
                        new_cost = cost + nxt
                        if new_cost < distance[nxt]:
                            distance[nxt] = new_cost
                            heapq.heappush(queue, (new_cost, nxt))

        return -1

