import heapq
class Solution:
    def minOperations(self, n: int, m: int) -> int:
        L=len(str(n))
        N=10**L
        prime=[True]*N
        if N>0: prime[0]=False
        if N>1: prime[1]=False
        for i in range(2,int(N**0.5)+1):
            if prime[i]:
                prime[i*i:N:i]=[False]*(((N-1-i*i)//i)+1)
        if prime[n] or prime[m]: return -1
        inf=10**30
        dist=[inf]*N
        dist[n]=n
        pq=[(n,n)]
        powers=[10**i for i in range(L)]
        while pq:
            d,x=heapq.heappop(pq)
            if d!=dist[x]: continue
            if x==m: return d
            for p in powers:
                digit=(x//p)%10
                if digit<9:
                    y=x+p
                    if not (p==powers[-1] and y < p):
                        if not prime[y] and d+y<dist[y]:
                            dist[y]=d+y; heapq.heappush(pq,(d+y,y))
                if digit>0:
                    y=x-p
                    if not (p==powers[-1] and y < p):
                        if not prime[y] and d+y<dist[y]:
                            dist[y]=d+y; heapq.heappush(pq,(d+y,y))
        return -1

