from typing import List

class Solution:
    def beautifulSplits(self, nums: List[int]) -> int:
        n = len(nums)

        def z_algorithm(start):
            m = n - start
            z = [0] * m
            if m:
                z[0] = m
            left = right = 0
            for k in range(1, m):
                if k < right:
                    v = z[k - left]
                    z[k] = v if v < right - k else right - k
                while (k + z[k] < m and
                       nums[start + z[k]] == nums[start + k + z[k]]):
                    z[k] += 1
                if k + z[k] > right:
                    left, right = k, k + z[k]
            return z

        z0 = z_algorithm(0)
        answer = 0
        for i in range(1, n - 1):
            z = z_algorithm(i)
            first_condition = z0[i] >= i

            if first_condition:
                answer += max(0, n - 2 * i)

            # d is the length of the second subarray.  The third subarray
            # must be at least this long for the second condition.
            for d in range(1, (n - i) // 2 + 1):
                if z[d] >= d and not (first_condition and d >= i):
                    answer += 1

        return answer

