        reverse = [[] for _ in range(n)]
        weights = []
        for a, b, w in edges:
            reverse[b].append((a, w))
            weights.append(w)
        candidates = sorted(set(weights))

        def reachable(limit: int) -> bool:
            seen = [False] * n
            seen[0] = True
            stack = [0]
            count = 1
            while stack:
                v = stack.pop()
                for u, w in reverse[v]:
                    if w <= limit and not seen[u]:
                        seen[u] = True
                        count += 1
                        stack.append(u)
            return count == n

        if not reachable(candidates[-1]):
            return -1
        left, right = 0, len(candidates) - 1
        while left < right:
            mid = (left + right) // 2
            if reachable(candidates[mid]):
                right = mid
            else:
                left = mid + 1
        return candidates[left]

